<script setup>
// The horizontal sign lockup: one house-shaped plate wrapping the microphone
// and the wordmark. The wordmark is the product name set in Pacifico (SIL OFL
// 1.1) and outlined to a path, so it renders identically everywhere with no
// font dependency and no brand string in the DOM. `size` is the lockup's
// HEIGHT (the plate is 1320:560, so width follows at ~2.36x); it is applied
// as CSS, never as SVG attributes, so clamp()/vmin values are valid.
import { computed } from 'vue'
import { BRAND_NAME } from '@/brand'

const props = defineProps({
  size: { type: [Number, String], default: 32 },
})

const cssSize = computed(() =>
  typeof props.size === 'number' ? `${props.size}px` : props.size,
)
</script>

